import ipaddress
nets = {"aws-kr-prod": "10.10.0.0/16", "aws-kr-alpha": "10.20.0.0/16",
        "aws-ca-prod": "10.30.0.0/16", "gcp-image": "10.20.128.0/20",
        "office-seoul": "172.16.0.0/20"}
items = [(k, ipaddress.ip_network(v)) for k, v in nets.items()]
for i, (a, na) in enumerate(items):
    for b, nb in items[i + 1:]:
        if na.overlaps(nb):
            print(f"overlap: {a} {na} <-> {b} {nb}")
# overlap: aws-kr-alpha 10.20.0.0/16 <-> gcp-image 10.20.128.0/20
